public List<List<Integer>> getSkyline(int[][] buildings) {
    List<int[]> events = new ArrayList<>();
    for (int[] b : buildings) {
        events.add(new int[]{b[0], -b[2]});   // start: negative height
        events.add(new int[]{b[1],  b[2]});   // end:   positive height
    }
    // sort by x; ties: start (neg) before end (pos); among starts, higher first (more negative first)
    events.sort((a, c) -> a[0] != c[0] ? Integer.compare(a[0], c[0]) : Integer.compare(a[1], c[1]));

    List<List<Integer>> res = new ArrayList<>();
    TreeMap<Integer, Integer> active = new TreeMap<>();   // height -> count
    active.put(0, 1);                                     // ground
    int prevMax = 0;
    for (int[] e : events) {
        int h = e[1];
        if (h < 0) active.merge(-h, 1, Integer::sum);     // start
        else {                                            // end
            int c = active.get(h);
            if (c == 1) active.remove(h); else active.put(h, c - 1);
        }
        int curMax = active.lastKey();
        if (curMax != prevMax) {
            res.add(Arrays.asList(e[0], curMax));
            prevMax = curMax;
        }
    }
    return res;
}

public List<Integer> fallingSquares(int[][] positions) {
    TreeSet<Integer> set = new TreeSet<>();
    for (int[] p : positions) { set.add(p[0]); set.add(p[0] + p[1]); }
    Map<Integer, Integer> idx = new HashMap<>();
    int c = 0;
    for (int x : set) idx.put(x, c++);
    int leaves = Math.max(1, c - 1);           // gaps between coordinates
    SegTree seg = new SegTree(leaves);

    List<Integer> res = new ArrayList<>();
    int best = 0;
    for (int[] p : positions) {
        int l = idx.get(p[0]);
        int r = idx.get(p[0] + p[1]) - 1;      // inclusive gap range
        int cur = seg.queryMax(l, r);
        int h = cur + p[1];
        seg.assign(l, r, h);
        best = Math.max(best, h);
        res.add(best);
    }
    return res;
}

static class SegTree {
    int n;
    int[] max, lazy;                            // lazy==0 means 'no pending assign' (heights are >0)
    SegTree(int n) { this.n = n; max = new int[4 * n]; lazy = new int[4 * n]; }

    void assign(int l, int r, int val) { assign(1, 0, n - 1, l, r, val); }
    void assign(int node, int lo, int hi, int l, int r, int val) {
        if (r < lo || hi < l) return;
        if (l <= lo && hi <= r) { max[node] = val; lazy[node] = val; return; }
        push(node);
        int mid = (lo + hi) >>> 1;
        assign(2 * node, lo, mid, l, r, val);
        assign(2 * node + 1, mid + 1, hi, l, r, val);
        max[node] = Math.max(max[2 * node], max[2 * node + 1]);
    }

    int queryMax(int l, int r) { return queryMax(1, 0, n - 1, l, r); }
    int queryMax(int node, int lo, int hi, int l, int r) {
        if (r < lo || hi < l) return 0;
        if (l <= lo && hi <= r) return max[node];
        push(node);
        int mid = (lo + hi) >>> 1;
        return Math.max(queryMax(2 * node, lo, mid, l, r), queryMax(2 * node + 1, mid + 1, hi, l, r));
    }

    private void push(int node) {
        if (lazy[node] != 0) {
            int v = lazy[node];
            max[2 * node] = v;     lazy[2 * node] = v;
            max[2 * node + 1] = v; lazy[2 * node + 1] = v;
            lazy[node] = 0;
        }
    }
}

class RangeModule {
    private final TreeMap<Integer, Integer> map = new TreeMap<>();   // start -> end

    public void addRange(int left, int right) {
        Integer s = map.floorKey(left);
        if (s != null && map.get(s) >= left) left = s;                 // merge left neighbor
        Map.Entry<Integer, Integer> e = map.floorEntry(right);
        if (e != null && e.getValue() > right) right = e.getValue();   // merge right neighbor
        map.subMap(left, true, right, true).clear();                   // absorb covered intervals
        map.put(left, right);
    }

    public boolean queryRange(int left, int right) {
        Integer s = map.floorKey(left);
        return s != null && map.get(s) >= right;
    }

    public void removeRange(int left, int right) {
        Map.Entry<Integer, Integer> hi = map.lowerEntry(right);
        Map.Entry<Integer, Integer> lo = map.lowerEntry(left);
        if (hi != null && hi.getValue() > right) map.put(right, hi.getValue());   // right tail
        if (lo != null && lo.getValue() > left)  map.put(lo.getKey(), left);      // left head
        map.subMap(left, true, right, false).clear();
    }
}

class MyCalendarThree {
    private final TreeMap<Integer, Integer> delta = new TreeMap<>();

    public int book(int start, int end) {
        delta.merge(start, 1, Integer::sum);
        delta.merge(end, -1, Integer::sum);
        int running = 0, max = 0;
        for (int d : delta.values()) {
            running += d;
            max = Math.max(max, running);
        }
        return max;
    }
}

class MyCalendarThree {
    private static final int MAX = 1_000_000_000;
    private final Node root = new Node();

    public int book(int start, int end) {
        update(root, 0, MAX, start, end - 1, 1);
        return root.max;
    }

    private void update(Node node, int lo, int hi, int l, int r, int val) {
        if (r < lo || hi < l) return;
        if (l <= lo && hi <= r) { node.max += val; node.lazy += val; return; }
        pushDown(node);
        int mid = lo + (hi - lo) / 2;
        update(node.left, lo, mid, l, r, val);
        update(node.right, mid + 1, hi, l, r, val);
        node.max = Math.max(node.left.max, node.right.max);
    }

    private void pushDown(Node node) {
        if (node.left == null) node.left = new Node();
        if (node.right == null) node.right = new Node();
        if (node.lazy != 0) {
            node.left.max += node.lazy;  node.left.lazy += node.lazy;
            node.right.max += node.lazy; node.right.lazy += node.lazy;
            node.lazy = 0;
        }
    }

    private static class Node {
        Node left, right;
        int max, lazy;
    }
}

public int lengthOfLIS(int[] nums, int k) {
    int max = 0;
    for (int x : nums) max = Math.max(max, x);
    SegTree seg = new SegTree(max);      // values 1..max
    int ans = 0;
    for (int x : nums) {
        int lo = Math.max(1, x - k);
        int best = seg.query(lo, x - 1); // best dp for values in [x-k, x-1]
        int cur = best + 1;
        ans = Math.max(ans, cur);
        seg.update(x, cur);
    }
    return ans;
}

static class SegTree {
    int n;
    int[] tree;
    SegTree(int size) { n = size; tree = new int[4 * n]; }

    void update(int pos, int val) { update(1, 1, n, pos, val); }
    void update(int node, int lo, int hi, int pos, int val) {
        if (lo == hi) { tree[node] = Math.max(tree[node], val); return; }
        int mid = (lo + hi) >>> 1;
        if (pos <= mid) update(2 * node, lo, mid, pos, val);
        else            update(2 * node + 1, mid + 1, hi, pos, val);
        tree[node] = Math.max(tree[2 * node], tree[2 * node + 1]);
    }

    int query(int l, int r) { if (l > r) return 0; return query(1, 1, n, l, r); }
    int query(int node, int lo, int hi, int l, int r) {
        if (r < lo || hi < l) return 0;
        if (l <= lo && hi <= r) return tree[node];
        int mid = (lo + hi) >>> 1;
        return Math.max(query(2 * node, lo, mid, l, r), query(2 * node + 1, mid + 1, hi, l, r));
    }
}
